/* demo.js — loaded ONLY when CONFIG.API_URL is empty. A pretend server with sample people.
 * It follows the same rules as the real server so the demo behaves like the live system. */
const DemoServer = (() => {
  const LOGO = 'data:image/jpeg;base64,';
  const PDF = '';
  const MAX = { CA1: 20, CA2: 20, EXAM: 60 };
  const AFF = ['Position Comment', 'Attendance', 'Conduct', 'Neatness', 'Punctuality', 'Games'], LV = ['Excellent', 'V.Good', 'Good', 'Fair', 'Poor'], SC = ['A', 'B', 'C', 'D', 'F'];
  const COMMENTS = { A: 'An outstanding result! Keep up the excellent work and good conduct.', B: 'A very good result! A little more effort will take you to the top.', C: 'A solid result! With consistent effort, you have the potential to achieve even greater success.', D: 'A fair result. Put in more effort and seek help in your weak subjects.', E: 'Below expectations. Put in greater focus and dedication, and seek support to strengthen your performance.', F: 'Significant improvement is necessary. Take this opportunity to build a stronger foundation.' };
  const STAFF = { 'STAFF/011': { pin: '1234', name: 'Hauwa Sani Musa', subjects: [{ classId: '134', className: 'Primary 2', subCode: 'PR-101', subject: 'English Language' }, { classId: '134', className: 'Primary 2', subCode: 'PR-102', subject: 'Mathematics' }], cm: [{ classId: '134', className: 'Primary 2' }] },
                  'STAFF/012': { pin: '5678', name: 'Musa Garba Idris', subjects: [{ classId: '135', className: 'Primary 5', subCode: 'PR-101', subject: 'English Language' }], cm: [] } };
  const KIDS = { '134': ['Maryam Sule Ahmad', 'Yusuf Nasir Danladi', 'Hafsat Kabir Umar', 'Abubakar Salisu Bala', 'Ruqayya Isa Aminu', 'Sadiq Muhammad Rabiu'], '135': ['Aisha Bello Garba', 'Umar Faruk Sani', 'Fatima Yusuf Idris'] };
  let seed = 9; const rnd = n => { seed = (seed * 16807) % 2147483647; return seed % n; };
  const ROWS = []; let id = 260100;
  Object.keys(KIDS).forEach(c => KIDS[c].forEach(nm => { id++; ['PR-101', 'PR-102'].forEach(sc => ROWS.push({ id: '2025/20263RD Term' + c + id + sc, classId: c, subCode: sc, sid: String(id), idn: 'ARF/' + id, name: nm, ca1: rnd(3) ? String(5 + rnd(15)) : '', ca2: rnd(3) ? String(5 + rnd(15)) : '', exam: '' })); }));
  const RAT = {}, TOK = {}, FAILS = {}, EXAMS = {};
  const PARENTS = { '260101': { pin: '482913', gsm: '08030000001' } };
  const err = m => ({ ok: false, error: m }), good = d => ({ ok: true, data: d });
  const who = t => TOK[t];
  const grade = a => a >= 85 ? 'A' : a >= 75 ? 'B' : a >= 50 ? 'C' : a >= 45 ? 'D' : a >= 40 ? 'E' : 'F';
  function score(v, max, label) { const t = String(v || '').trim(); if (t === '') return ''; if (!/^\d{1,3}(\.5)?$/.test(t)) throw label + ': "' + t + '" is not a valid score.'; if (+t > max) throw label + ': ' + t + ' is more than the maximum of ' + max + '.'; return t; }
  const routes = {
    branding: () => good({ name: 'ARFAT MODEL ACADEMY KANO', motto: 'Education with Quality', addr: 'School address · GSM numbers', logo: LOGO, session: '2025/2026', term: '3RD Term' }),
    staffLogin: p => {
      const k = String(p.staffId || '').trim().toUpperCase(), s = STAFF[k];
      if ((FAILS[k] || 0) >= 5) return err('Too many wrong attempts. Try again after 15 minutes.');
      if (!s || s.pin !== String(p.pin || '').trim()) { FAILS[k] = (FAILS[k] || 0) + 1; return err('Staff ID or PIN is not correct.'); }
      const t = Math.random().toString(16).slice(2).padEnd(64, '0').slice(0, 64); TOK[t] = k;
      return good({ token: t, name: s.name, staffId: k, session: '2025/2026', term: '3RD Term', subjects: s.subjects, cmClasses: s.cm, max: MAX });
    },
    getScores: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      const al = STAFF[k].subjects.find(x => x.classId === p.classId && x.subCode === p.subCode); if (!al) return err('This subject is not allocated to you this term.');
      return good(Object.assign({}, al, { max: MAX, locked: false, rows: ROWS.filter(r => r.classId === al.classId && r.subCode === al.subCode).map(r => Object.assign({}, r)) }));
    },
    saveScores: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      const al = STAFF[k].subjects.find(x => x.classId === p.classId && x.subCode === p.subCode); if (!al) return err('This subject is not allocated to you this term.');
      try {
        const w = p.scores.map(x => { const r = ROWS.find(y => y.id === x.id && y.classId === al.classId && y.subCode === al.subCode); if (!r) throw 'A student row was not found. Reload the page and try again.'; return { r, v: [score(x.ca1, MAX.CA1, r.name + ' CA1'), score(x.ca2, MAX.CA2, r.name + ' CA2'), score(x.exam, MAX.EXAM, r.name + ' Exam')] }; });
        w.forEach(x => { [x.r.ca1, x.r.ca2, x.r.exam] = x.v.map(String); });
        return good({ saved: w.length });
      } catch (m) { return err(String(m)); }
    },
    cmClass: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      const c = STAFF[k].cm.find(x => x.classId === p.classId); if (!c) return err('You are not the Class Master of this class this term.');
      const sids = [...new Set(ROWS.filter(r => r.classId === c.classId).map(r => r.sid))];
      return good({ className: c.className, classId: c.classId, locked: false, items: AFF, levels: LV, scales: SC,
        students: sids.map(sid => { const rs = ROWS.filter(r => r.sid === sid); const avg = Math.round(rs.reduce((a, r) => a + (+r.ca1 || 0) + (+r.ca2 || 0) + (+r.exam || 0), 0) / rs.length); const g = grade(avg); const R = RAT[sid];
          return { sid, idn: rs[0].idn, name: rs[0].name, grade: g, autoComment: COMMENTS[g], comment: (R && R.comment) || COMMENTS[g], aff: R ? R.aff : AFF.map(() => -1), att: R ? R.att : '', hw: R ? R.hw : '', complete: !!R }; }) });
    },
    cmSave: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      if (!STAFF[k].cm.find(x => x.classId === p.classId)) return err('You are not the Class Master of this class this term.');
      if (!Array.isArray(p.aff) || p.aff.length !== 6 || p.aff.some(v => !(v >= 0 && v < 5))) return err('Rate all 6 Affective Domain items.');
      if (SC.indexOf(String(p.att).toUpperCase()) < 0 || SC.indexOf(String(p.hw).toUpperCase()) < 0) return err('Choose both the Attendance and Handwriting scales.');
      RAT[p.sid] = { aff: p.aff, att: p.att, hw: p.hw, comment: String(p.comment || '').slice(0, 160) };
      return good({ saved: true, sid: p.sid });
    },
    examStatus: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      return good({ papers: STAFF[k].subjects.map(x => { const e = EXAMS[x.classId + x.subCode] || { status: x.subCode === 'PR-102' ? 'Returned' : 'Not uploaded', note: x.subCode === 'PR-102' ? 'Question 14 has no option (d). Please correct and upload again.' : '' };
        return Object.assign({}, x, { status: e.status, note: e.note || '', uploadedAt: e.at || '' }); }) });
    },
    examUpload: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      const al = STAFF[k].subjects.find(x => x.classId === p.classId && x.subCode === p.subCode); if (!al) return err('This subject is not allocated to you this term.');
      if (!String(p.b64 || '').startsWith('JVBER')) return err('Only PDF files are accepted. In Word use File > Save As > PDF, then upload that file.');
      EXAMS[al.classId + al.subCode] = { status: 'Submitted', note: '', at: '2026-11-25 11:30', b64: p.b64 };
      return good({ status: 'Submitted' });
    },
    examDownload: p => {
      const k = who(p.token); if (!k) return err('Your session has expired. Please sign in again.');
      const e = EXAMS[p.classId + p.subCode]; if (!e || !e.b64) return err('You have not uploaded this paper yet.');
      return good({ fileName: 'my-paper.pdf', b64: e.b64 });
    },
    parentResult: p => {
      const sid = String(p.studentId || '').trim(), P = PARENTS[sid], g = String(p.gsm || '').replace(/\D/g, '').slice(-10);
      if (!sid || !p.pin || g.length < 10) return err('Enter Student ID, Parents PIN and the parent phone number.');
      if (!P || P.pin !== String(p.pin).trim() || P.gsm.slice(-10) !== g) return err('The details do not match our records. Check and try again.');
      return good({ name: 'Maryam Sule Ahmad', term: '3RD Term', session: '2025/2026', cls: 'Primary 2', fileName: sid + ' 3RD Term.pdf', b64: PDF });
    }
  };
  return {
    handle: b => routes[b.action] ? routes[b.action](b) : err('Unknown request.'),
    help: () => '<b>Demo sign-in details</b><br>Score Entry / Class Master: <b>STAFF/011</b> PIN <b>1234</b> (2 subjects + Class Master of Primary 2) · <b>STAFF/012</b> PIN <b>5678</b><br>Parent Portal: Student ID <b>260101</b>, Parents PIN <b>482913</b>, phone <b>0803 000 0001</b> (or +234 803 000 0001)'
  };
})();
